            function showImagePages(title, pages, backFunction, keyPrefix) {
                let currentPage = 0;
                infoCardTitle.textContent = title;
                infoCardContent.innerHTML = `
                    <div class="christos-reader" dir="rtl">
                        <div class="christos-toolbar">
                            <button type="button" class="christos-back" id="${keyPrefix}BackBtn">
                                <svg class="icon fa-solid fa-arrow-right" style="" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m10 5 7 7-7 7M17 12H3"/></svg> الألحان
                            </button>
                            <span class="christos-counter" id="${keyPrefix}Counter">صفحة 1 من ${pages.length}</span>
                            <div style="display:flex;gap:6px;">
                                <button type="button" id="${keyPrefix}PrevBtn">السابق</button>
                                <button type="button" id="${keyPrefix}NextBtn">التالي</button>
                            </div>
                        </div>
                        <div class="christos-page">
                            <img loading="lazy" decoding="async" id="${keyPrefix}PageImage" src="${pages[0]}" alt="">
                        </div>
                    </div>`;

                hideAllMainViews();
                infoCard.classList.remove('hidden');

                const img = document.getElementById(`${keyPrefix}PageImage`);
                const counter = document.getElementById(`${keyPrefix}Counter`);
                const prev = document.getElementById(`${keyPrefix}PrevBtn`);
                const next = document.getElementById(`${keyPrefix}NextBtn`);
                const back = document.getElementById(`${keyPrefix}BackBtn`);

                function render() {
                    img.src = pages[currentPage];
                    img.alt = title + ' - الصفحة ' + (currentPage + 1);
                    counter.textContent = 'صفحة ' + (currentPage + 1) + ' من ' + pages.length;
                    prev.disabled = currentPage === 0;
                    next.disabled = currentPage === pages.length - 1;
                }

                prev.addEventListener('click', () => {
                    if (currentPage > 0) { currentPage--; render(); }
                });
                next.addEventListener('click', () => {
                    if (currentPage < pages.length - 1) { currentPage++; render(); }
                });
                back.addEventListener('click', backFunction);
                render();
            }


